def solve(x):
    if max(x) > 40:
        return 0
    dp = [1] * len(x)
    for i in range(len(x)):
        for j in range(i):
            if x[j] < x[i]:
                dp[i] = max(dp[i], dp[j] + 1)
    return max(dp) if len(x) > 0 else 0

